 {show&&<Modal title="Trust Deposit / Disbursement" onClose={()=>setShow(false)}><form onSubmit={saveTrust}><div className="formgrid"><label>Trust account<select required value={form.bank_account_id} onChange={e=>setForm({...form,bank_account_id:e.target.value})}><option value="">Select</option>{trustAccounts.map(x=><option key={x.id} value={x.id}>{x.name} · {x.account_type.replaceAll("_"," ")}</option>)}</select></label><label>Type<select value={form.direction} onChange={e=>setForm({...form,direction:e.target.value})}><option>DEPOSIT</option><option>DISBURSEMENT</option></select></label><label>Date<input type="date" required value={form.ledger_date} onChange={e=>setForm({...form,ledger_date:e.target.value})}/></label><label>Client / Beneficiary<input required value={form.client_name} onChange={e=>setForm({...form,client_name:e.target.value})}/></label><label>Matter / Deal<input value={form.matter} onChange={e=>setForm({...form,matter:e.target.value})}/></label><label>Description<input required value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><label>Amount<input type="number" step=".01" min=".01" required value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></label><label>Reference<input value={form.reference} onChange={e=>setForm({...form,reference:e.target.value})}/></label></div><div className="notice"><AlertCircle/> This posts to the trust ledger and bank activity automatically. It does not recognize revenue or HST.</div><div className="modalactions"><button type="button" className="secondary" onClick={()=>setShow(false)}>Cancel</button><button className="primary"><Save/> Post Trust Activity</button></div></form></Modal>}
