  const payload={company_id:companyId,agent_number:editId&&isSuperAdmin?form.agent_number.trim()||null:undefined,first_name:form.first_name.trim(),last_name:form.last_name.trim(),name:[form.first_name,form.last_name].filter(Boolean).join(" ").trim(),legal_name:form.legal_name.trim()||null,incorporated:!!form.incorporated,corporation_name:form.incorporated?form.corporation_name.trim()||null:null,spouse_name:form.spouse_name.trim()||null,address:form.address.trim()||null,city:form.city.trim()||null,province:form.province,postal_code:form.postal_code.trim()||null,email:form.email.trim()||null,cell_phone:form.cell_phone.trim()||null,date_of_birth:form.date_of_birth||null,start_date:form.start_date||null,anniversary_date:form.anniversary_date||null,termination_date:form.termination_date||null,incorporation_date:form.incorporated?(form.incorporation_date||null):null,reco_license_number:form.reco_license_number.trim()||null,reco_license_expiry:form.reco_license_expiry||null,branch_id:form.branch_id||null,hst_number:form.incorporated?null:(form.hst_number.trim()||null),prec_hst_number:form.incorporated?(form.prec_hst_number.trim()||null):null};
  let data,error;if(editId){const r=await supabase.from("dv_accounting_agents").update(payload).eq("id",editId).select().single();data=r.data;error=r.error}else{delete payload.agent_number;const r=await supabase.from("dv_accounting_agents").insert([payload]).select().single();data=r.data;error=r.error}
  if(error)throw new Error("Could not save agent: "+error.message);a.setRows(z=>editId?z.map(x=>x.id===data.id?data:x):[data,...z]);
  const agentId=data.id;
