  const bankPayload={agent_id:agentId,bank_name:form.bank_name.trim()||null,institution_number:form.institution_number.trim()||null,transit_number:form.transit_number.trim()||null,account_number:form.account_number.trim()||null,account_type:form.account_type||null,account_name:form.account_name.trim()||null};
  const be=await supabase.from("dv_accounting_agent_bank_details").upsert(bankPayload,{onConflict:"agent_id"});if(be.error)throw new Error("Agent was saved, but bank details could not be saved: "+be.error.message);
  const hasFees=form.fee_plan_id||form.desk_fee_override!==""||form.admin_fee_override!==""||form.lead_fee_override!==""||form.commission_split_override_percent!==""||form.lead_fee_buy_sell_type||form.lead_fee_lease_type;
  if(editId || agentId){ await supabase.rpc("dv_accounting_sync_agent_desk_fee_subscription",{p_agent_id:agentId,p_start_date:form.start_date||today()}); }
  if(hasFees){
   const feePayload={agent_id:agentId,fee_plan_id:form.fee_plan_id||null,desk_fee_override:form.desk_fee_override===""?null:Number(form.desk_fee_override),admin_fee_override:form.admin_fee_override===""?null:Number(form.admin_fee_override),lead_fee_override:form.lead_fee_override===""?null:Number(form.lead_fee_override),lead_fee_buy_sell_type:form.lead_fee_buy_sell_type||null,lead_fee_buy_sell_value:form.lead_fee_buy_sell_value===""?null:Number(form.lead_fee_buy_sell_value),lead_fee_lease_type:form.lead_fee_lease_type||null,lead_fee_lease_value:form.lead_fee_lease_value===""?null:Number(form.lead_fee_lease_value),commission_split_override_percent:form.commission_split_override_percent===""?null:Number(form.commission_split_override_percent),notes:form.fee_notes.trim()||null,effective_date:form.effective_from||form.start_date||today(),effective_from:form.effective_from||form.start_date||today(),effective_to:form.effective_to||null,is_promotion:!!form.promotion};
   const fe=await supabase.from("dv_accounting_agent_fee_settings").upsert(feePayload,{onConflict:"agent_id"});if(fe.error)throw new Error("Agent was saved, but fee settings could not be saved: "+fe.error.message);
  }
