 async function saveService(e){e.preventDefault();if(!supabase||!companyId)return;const p={company_id:companyId,agent_id:serviceForm.agent_id,service_type:"ADD_ON",name:serviceForm.name.trim(),amount:Number(serviceForm.amount||0),hst_amount:Number(serviceForm.hst_amount||0),frequency:serviceForm.frequency,start_date:serviceForm.start_date,end_date:serviceForm.end_date||null,next_charge_date:serviceForm.next_charge_date||serviceForm.start_date,notes:serviceForm.notes.trim()||null,active:true};let data,error;if(serviceEditId){const r=await supabase.from("dv_accounting_agent_service_subscriptions").update(p).eq("id",serviceEditId).select().single();data=r.data;error=r.error}else{const r=await supabase.from("dv_accounting_agent_service_subscriptions").insert([p]).select().single();data=r.data;error=r.error}if(error)return alert(error.message);serviceSubs.setRows(r=>serviceEditId?r.map(x=>x.id===data.id?data:x):[data,...r]);setServiceShow(false);setServiceEditId(null);setServiceForm({agent_id:"",name:"",amount:"",hst_amount:"0",frequency:"MONTHLY",start_date:today(),end_date:"",next_charge_date:today(),notes:""})}
 async function runRecurring(){if(!supabase)return;setRunning(true);const r1=await supabase.rpc("dv_accounting_run_recurring_fees",{p_run_date:today()});const r2=await supabase.rpc("dv_accounting_run_agent_service_billing",{p_run_date:today()});if(r1.error||r2.error)alert((r1.error||r2.error).message);else alert("Recurring billing processed: "+((r1.data?.created_count||0)+(r2.data?.created_count||0))+" item(s).");await recurring.load();await serviceSubs.load();setRunning(false)}
 async function editPlan(p){setPlanEditId(p.id);setPlanForm({...planForm,name:p.name||"",desk_fee:p.desk_fee??"0",desk_fee_frequency:p.desk_fee_frequency||"MONTHLY",admin_fee_buy_sell_type:p.admin_fee_buy_sell_type||"AMOUNT",admin_fee_buy_sell_value:p.admin_fee_buy_sell_value??"0",admin_fee_lease_type:p.admin_fee_lease_type||"AMOUNT",admin_fee_lease_value:p.admin_fee_lease_value??"0",admin_fee_commercial_buy_sell_type:p.admin_fee_commercial_buy_sell_type||"AMOUNT",admin_fee_commercial_buy_sell_value:p.admin_fee_commercial_buy_sell_value??"0",admin_fee_commercial_lease_type:p.admin_fee_commercial_lease_type||"AMOUNT",admin_fee_commercial_lease_value:p.admin_fee_commercial_lease_value??"0",lead_fee_buy_sell_type:p.lead_fee_buy_sell_type||"AMOUNT",lead_fee_buy_sell_value:p.lead_fee_buy_sell_value??"0",lead_fee_lease_type:p.lead_fee_lease_type||"AMOUNT",lead_fee_lease_value:p.lead_fee_lease_value??"0",commission_split_percent:p.commission_split_percent??"90"});setPlanShow(true)}
